    @PutMapping("/settings/proof-threshold/{grade}")
    public SettingsView setGradeProofThreshold(
            @PathVariable @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable @Pattern(regexp = "[ABC]") String grade,
